import{_ as t,c as l,j as e,a as n,o as r}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易做到了不预测、只跟随，后面应该怎么做？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/不预测/预测市场与不预测理解.md","filePath":"stock/不预测/预测市场与不预测理解.md"}'),o={name:"stock/不预测/预测市场与不预测理解.md"};function s(_,a,c,p,d,i){return r(),l("div",null,a[0]||(a[0]=[e("h1",{id:"交易做到了不预测、只跟随-后面应该怎么做",tabindex:"-1"},[n("交易做到了不预测、只跟随，后面应该怎么做？ "),e("a",{class:"header-anchor",href:"#交易做到了不预测、只跟随-后面应该怎么做","aria-label":'Permalink to "交易做到了不预测、只跟随，后面应该怎么做？"'},"​")],-1),e("p",null,"选择了顺应市场是思维层面，做到了顺应市场是执行层面，从认知到执行就是知行合一的过程。",-1),e("p",null,"“做到了”并不是事情的终点，”所谓的“做到了”也有不同的程度，就像爱因斯坦的三个凳子的故事一样，做出来和做好，做好和做优，同样是“做出来”最后的东西是不一样的，类似学徒和匠人，匠人和大师的区别，中间每一步都是巨大的鸿沟。",-1),e("p",null,"从你的描述来看，你对顺势的理解还是有点单薄，有点书面化的。顺势最直观的作用有两个，第一个增加盈利的概率，所谓的天下大势，顺之则昌，逆之则亡。第二个它其实也是一种风控的手段，避免个人的主观执念与市场实际走势产生冲突导致大的亏损。",-1),e("p",null,"跟势交易是一种后发的交易模式，市场运行的方向，就是你的操作方向，一旦入场，以实际走势为准，市场给你利润，走的正常，你就安安心心拿着，不要因为主观的恐惧急躁或者他人的看空意见就着急兑现；市场不给你利润，入场就打你止损，不管你前面有多少的理由看多，把风险控制住，控制在合理范围内，能承受的范围内，这个时候你的看法想法都不重要，活下来最重要。",-1),e("p",null,"总体来说，事前事后你都可以有自己主观的判断和预测，可以跟别人扯淡看好或者看空，不过你的看多看空观点对市场一点影响都没有。一旦实际入场，市场为准，风控第一，你的主观想法看法不重要。跟势交易更多的不是体现在你的观点上，而是体现在你的应对上，针对不同的市场情形进行合理准确的应对，这个应对过程不是僵化的，不是一成不变的，不是照本宣科，肯定是灵活机动的，贴合实际的，很多时候你会发现即便市场给出同样的走势信号，但是由于各种外在条件的不同，你需要采取的应对策略是不同的，这就需要的不断积累总结经验，所以交易不存在无事可做的情况。",-1),e("p",null,"交易需要的是终身学习，是一个完善自我的过程，也是一个不断成长的过程，这个过程不是单点或者线性的，而是一个复杂的体系，涵盖对市场和自我的正确认知，交易技术和策略的改进和提高，人性弱点的克服和完善等等内容，认知到需要顺应市场、顺势而为只是其中的一部分内容。市场在变，人也在成长，交易是个没有终点的事业，只要你还在市场里，只要你还想精进，其实就有无数的事情要做，哪怕你随便拿一笔自己的交易复复盘，你就能发现不少不完美能改进的地方，如果你确实不知道后面要做什么，那只能说明你需要做的事情还非常的多。",-1)]))}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
